from typing import Any,Mapping
from counterexamples.generators import generate
from studies.granular_ball_core import fit_tree_frontier,reference_metrics
def run(config:Mapping[str,Any]):
 p=config['dataset_generation_parameters'];seed=int(config['seed']);base={'manifold_width':p.get('manifold_width',.08),'overlap':p.get('overlap',.15),'curvature':p.get('curvature',2.)};X,clean,_=generate(p['family'],n_samples=600,seed=seed,**base);X2,noisy,meta=generate(p['family'],n_samples=600,seed=seed,label_noise=p['noise_kind'],noise_rate=p['noise_rate'],**base);Xt,yt,_=generate(p['family'],n_samples=1200,seed=seed+10000,**base);assert (X==X2).all();frontier=fit_tree_frontier(X,noisy,Xt,yt,p['generation_method'],seed);refs=reference_metrics(X,noisy,Xt,yt,seed);primary=next(x for x in frontier if x['tau']==.85);best_ref=max(v['accuracy'] for v in refs.values())
 return {'metrics':{'accuracy':primary['accuracy'],'macro_f1':primary['macro_f1'],'auroc':None,'calibration_error':primary['ece'],'additional':{'frontier':frontier,'references':refs,'best_reference_accuracy':best_ref,'accuracy_gap':primary['accuracy']-best_ref,'actual_noise_rate':float((clean!=noisy).mean()),'label_flips':len(meta['label_flips'])}},'structure':{'granule_count':primary['granules'],'average_granule_size':primary['mean_size'],'uncertain_sample_ratio':None,'additional':{'fragmentation_ratio':primary['fragmentation_ratio'],'mean_purity':primary['mean_purity']}},'outcome':'success','notes':'GB-only clean-test label-noise stress; features are identical before/after label corruption.'}
